@startuml

class HospitalHouseMD {}

class Patient {
  + name : string
}

class Doctor {
  + name : string
}

class Diagnosis {
  + description : string
}

class Treatment {
  + name : string
}

class ConsentForm {
  + signature : string
}

class Illness {
  + name : string
}

enum PriorityScore {
  High
  Low
}

enum TreatmentStage {
  Stage1
  Stage2
  Stage3
}

HospitalHouseMD "1" -- "*" Patient
Patient "1" -- "*" Doctor
Doctor "1" -- "*" Diagnosis
Patient "1" -- "*" Treatment
Diagnosis "1" -- "*" Treatment
Illness "1" -- "*" Diagnosis
Illness "1" -- "*" Treatment
Illness "*" -- "1" PriorityScore

Treatment "1" -- "1" TreatmentStage
ConsentForm "1" -- "1" Patient
ConsentForm "1" -- "0..*" Treatment

class HeadDoctor extends Doctor {}

HeadDoctor "1" -- "*" Diagnosis : approves

@enduml

